      "كل اللي بيوصلك من جواك ومن حواليك بيعدي على الميزان ده الأول: ده صح ولا غلط؟ فاللي بيطابق بيعدي بصمت وما بيوقفكش، واللي بيخالف بينور بقوة ويشد نظرك له.",
