    "m2.a2.giftCost": [
      "كل باب فيه مكسب وفيه تمن. والاتنين بييجوا مع بعض.",
      "المكسب:",
      "إنت بتشوف اللي حواليك بدقة قليل اللي بيوصل لها.",
      "بتدخل مكان وفي دقيقة تكون قريته. مين مرتاح ومين لأ، وفين الحاجة اللي محتاجة حد، وإيه اللي ممكن يتعمل.",
      "والقدرة دي مش رفاهية. الدنيا ماشية بناس زيك.",
      "فيه ناس كتير حواليك اتشالت وهي مش عارفة مين شايلها. وفيه فرص اتفتحت لناس ما كانوش هيشوفوها. وفيه مواقف ما وصلتش لخناقة لأن حد قرا الموقف صح وتحرك في وقته.",
      "وإنت غالبا مش حاسب ده مهارة. حاسبه حاجة عادية، وبتستغرب إن فيه ناس مش شايفة اللي إنت شايفه.",
      "وهي مش عادية. دي أحسن حاجة فيك.",
      "والتمن:",
      "إن الخريطة اللي بترسمها مفيهاش إنت.",
      "يعني بتعرف عن الناس أكتر مما تعرف عن نفسك بكتير. ولو حد سألك إنت محتاج إيه دلوقتي، السؤال هيقف قدامك.",
      "ومش لأنك مش عارف. لأن السؤال نفسه غريب.",
      "وفيه تمن تاني، وده بيوجع أكتر:",
      "إنت بتشوف احتياج الناس بوضوح مذهل، ومش بتشوف إنهم شايفينك.",
      "فممكن يكون فيه ناس حواليك قلقانة عليك، وسايبالك مساحة، ومستنياك تتكلم. وإنت مش شايف ده، لأن كشافك رايح ناحية احتياجهم مش ناحية اهتمامهم بيك.",
      "فبتحس إنك لوحدك، وسط ناس إنت مش لوحدك معاهم أصلا.",
      "والعلامة اللي بتفرق:",
      "بعد أي قعدة، لما تقعد لوحدك، عدت كام دقيقة قبل ما نظرك يروح لبره تاني؟",
      "لو بتقدر ترجع لنفسك وتفضل، فالكشاف بيخدمك في الاتجاهين.",
      "ولو بتفضل لحظة وبعدين تلاقي نفسك رجعت لبره من غير قرار، فالكشاف بيخدمهم هما بس."
    ],

