        "الأول: بتحضر لاحتمالات إنت عارف إنها بعيدة. وإنت عارف إنها بعيدة وبتحضر لها برضه. ولو حد قال لك إن دي مش هتحصل، هتوافقه، وهتحضر.",
        "والتاني: بعد ما تاخد رأي وتطمن، الطمأنينة بتقعد فترة قصيرة، وبعدين بتتحول لسؤال جديد. وإنت مش حاسس إنك بترجع، إنت حاسس إن فيه زاوية جديدة ظهرت.",
